local controller_base = get_or_create_global_variable('Quest/Base/QuestControllerBase')

---@class PixyWorldCompanionController : QuestControllerBase
local local_class = newclass('PixyWorldCompanionController', controller_base)

function local_class:init(cs_controller)
	self.super:init(cs_controller)

	-- 사용할 섹션 스크립트 정보
	self.script_config = {
		HasPreSection = false,
		NormalSectionCount = 1,
		HasPostSection = true
	}

	self.npc = {
		companion_blind = function()
			return get_character('companion_blind')
		end
	}

	self.object = {
		doodle = function()
			return get_field_object('companion_doodle')
		end,
	}

	self.markers = {
		pivot_pos = function()
			return field_util.get_marker_pos('companion_pos')
		end,
	}

	self.quest_name = 'pixyworld_companion'
end

function local_class:load_resource()
end

function local_class:dispose()
	self.super:dispose()
end

function local_class:on_event(e)
	return false
end

function local_class:on_stage_loaded()
end

function local_class:on_stage_end()
end

function local_class:narration_doodle()
	--바닥에 글자 하나가 쓰여져 있다.
	field_ui_util.show_narration_async({ key = 'pw_companion_s1_6' })

	--…큰 의미는 없어 보인다.
	field_ui_util.show_narration_async({ key = 'pw_companion_s1_7' })

end

function local_class:activate_npc()
	local npc = self.npc.companion_blind()
	local pivot_pos = self.markers.pivot_pos()

	npc.Position = pivot_pos
	scene_util.set_emotion(npc, self, 'smile')
	scene_util.set_anim(npc, self, 'idle')
	character_util.set_direction(npc, 'right')
	field_object_util.set_active_state(npc, active_state_type.enabled)

end

function local_class:deactivate_npc()
	local npc = self.npc.companion_blind()

	npc.Position = vector(999, 0, 999)
	field_object_util.set_active_state(npc, active_state_type.disabled)
end

function local_class:activate_object()
	local object = self.object.doodle()
	local pivot_pos = self.markers.pivot_pos()

	object.Position = pivot_pos
	field_object_util.set_active_state(object, active_state_type.enabled)

end

function local_class:deactivate_object()
	local object = self.object.doodle()

	object.Position = vector(999, 0, 999)
	field_object_util.set_active_state(object, active_state_type.disabled)
end

function local_class:set_object_interactable()
	self.object.Interactable = CS.Oak.PublishInteractable.Create()
end

return local_class

